import React, { useEffect, useRef, useState } from 'react';
import axios from 'axios';
import './App.css';

const defaultGrid = Array.from({ length: 10 }, () => Array.from({ length: 5 }, () => ''));

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function App() {
  const [title, setTitle] = useState('My Note');
  const [grid, setGrid] = useState(defaultGrid);
  const [noteId, setNoteId] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [showTranscript, setShowTranscript] = useState(false);
  const [recordingError, setRecordingError] = useState('');
  const mediaRecorderRef = useRef(null);
  const recognitionRef = useRef(null);
  const chunksRef = useRef([]);

  useEffect(() => {
    const fetchNote = async () => {
      try {
        const res = await axios.get('http://localhost:4000/note');
        if (res.data?.grid) {
          setTitle(res.data.title);
          setGrid(res.data.grid);
          setNoteId(res.data.id);
        }
      } catch (err) {
        console.warn('No note loaded', err.message);
      }
    };
    fetchNote();
  }, []);

  const updateCell = (rowIndex, colIndex, value) => {
    setGrid((prevGrid) =>
      prevGrid.map((row, r) =>
        row.map((cell, c) => (r === rowIndex && c === colIndex ? value : cell))
      )
    );
  };

  const addRow = () => {
    setGrid((prevGrid) => {
      const columnCount = prevGrid[0]?.length || 1;
      return [...prevGrid, Array.from({ length: columnCount }, () => '')];
    });
  };

  const addColumn = () => {
    setGrid((prevGrid) => prevGrid.map((row) => [...row, '']));
  };

  const deleteLastRow = () => {
    if (grid.length === 0) return;

    const lastRowIndex = grid.length - 1;
    const hasContent = grid[lastRowIndex]?.some((cell) => String(cell || '').trim());
    const confirmed = hasContent
      ? window.confirm('Delete the last row and its contents?')
      : true;

    if (!confirmed) return;

    setGrid((prevGrid) => prevGrid.slice(0, -1));
  };

  const deleteLastColumn = () => {
    if (grid.length === 0 || grid[0].length === 0) return;

    const lastColIndex = grid[0].length - 1;
    const hasContent = grid.some((row) => String(row[lastColIndex] || '').trim());
    const confirmed = hasContent
      ? window.confirm('Delete the last column and its contents?')
      : true;

    if (!confirmed) return;

    setGrid((prevGrid) => prevGrid.map((row) => row.slice(0, -1)));
  };

  const extractValueForHeader = (text, header) => {
    const normalizedHeader = normalizeText(header);
    if (!normalizedHeader) return '';

    const patterns = [
      new RegExp(`\\b${escapeRegExp(normalizedHeader)}\\b\\s*(?:is|was|=|:|-)\\s*([^.;\\n]+)`, 'i'),
      new RegExp(`\\b${escapeRegExp(normalizedHeader)}\\b[^\\n.;]*?([A-Za-z0-9._%+@/\\-]{2,})`, 'i')
    ];

    for (const pattern of patterns) {
      const match = text.match(pattern);
      if (match && match[1]) {
        return match[1].trim().replace(/[.,;]+$/g, '');
      }
    }

    const emailMatch = text.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
    if (normalizedHeader.includes('email') && emailMatch) {
      return emailMatch[1];
    }

    const phoneMatch = text.match(/(\+?\d[\d\s().-]{7,}\d)/);
    if (normalizedHeader.includes('phone') && phoneMatch) {
      return phoneMatch[1];
    }

    return '';
  };

  const fillFromTranscript = () => {
    if (!transcript.trim()) {
      alert('Record or paste a transcript first.');
      return;
    }

    const headers = (grid[0] || []).map((cell) => String(cell || ''));
    const rowValues = headers.map((header) => extractValueForHeader(transcript, header));
    const nextRow = rowValues.map((value) => value || '');

    setGrid((prevGrid) => [...prevGrid, nextRow]);
    setTranscript('');
    setShowTranscript(false);
  };

  const startRecording = async () => {
    try {
      setRecordingError('');
      setTranscript('');
      if (!navigator.mediaDevices?.getUserMedia) {
        throw new Error('Voice recording is not supported in this browser.');
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      chunksRef.current = [];
      recorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          chunksRef.current.push(event.data);
        }
      };
      recorder.onstop = () => {
        stream.getTracks().forEach((track) => track.stop());
      };
      recorder.start();
      mediaRecorderRef.current = recorder;

      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (SpeechRecognition) {
        const recognition = new SpeechRecognition();
        recognition.lang = 'en-US';
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.onresult = (event) => {
          const interimText = Array.from(event.results)
            .map((result) => result[0]?.transcript || '')
            .join(' ')
            .trim();
          setTranscript(interimText);
        };
        recognition.onerror = () => {
          setRecordingError('Speech recognition was interrupted.');
        };
        recognition.onend = () => {
          if (isRecording) {
            recognition.start();
          }
        };
        recognition.start();
        recognitionRef.current = recognition;
      }

      setIsRecording(true);
    } catch (err) {
      setRecordingError(err.message || 'Unable to start recording.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      recognitionRef.current = null;
    }
    setIsRecording(false);
  };

  const saveNote = async () => {
    try {
      const payload = { title, grid };
      const res = noteId
        ? await axios.put(`http://localhost:4000/note/${noteId}`, payload)
        : await axios.post('http://localhost:4000/note', payload);

      if (res?.data?.id) {
        setNoteId(res.data.id);
      }

      if (res?.data?.fallback) {
        alert('Saved locally (fallback mode)');
      } else {
        alert('Saved successfully');
      }
    } catch (err) {
      const message = err.response?.data?.error || err.message || 'Unknown error';
      alert(`Save failed: ${message}`);
    }
  };

  const exportExcel = async () => {
    try {
      const res = await axios.post('http://localhost:5000/export', { title, grid }, { responseType: 'blob' });
      const blob = new Blob([res.data], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `${title || 'note'}.xlsx`;
      link.click();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      alert('Export failed');
    }
  };

  return (
    <div className="app-shell">
      <header className="app-header">
        <div>
          <input className="title-input" value={title} onChange={(e) => setTitle(e.target.value)} />
        </div>
        <div className="action-row">
          <button onClick={addRow}>+ Row</button>
          <button onClick={deleteLastRow}>- Last Row</button>
          <button onClick={addColumn}>+ Column</button>
          <button onClick={deleteLastColumn}>- Last Column</button>
          <button onClick={isRecording ? stopRecording : startRecording}>
            {isRecording ? 'Stop Recording' : 'Start Recording'}
          </button>
          <button onClick={() => setShowTranscript((value) => !value)}>Transcript</button>
          <button onClick={fillFromTranscript}>AI Fill</button>
          <button onClick={saveNote}>Save</button>
          <button onClick={exportExcel}>Export XLSX</button>
        </div>
      </header>

      <main className="grid-scroll-area">
        {showTranscript && (
          <section className="transcript-panel">
            <h3>Transcript</h3>
            <p>{transcript || 'No transcript yet.'}</p>
            {recordingError ? <p className="transcript-error">{recordingError}</p> : null}
          </section>
        )}

        <div className="grid-container">
          {grid.map((row, rowIndex) => (
            <div className="grid-row" key={rowIndex} style={{ '--grid-columns': row.length || 1 }}>
              {row.map((cell, colIndex) => (
                <input
                  key={`${rowIndex}-${colIndex}`}
                  className="grid-cell"
                  value={cell}
                  onChange={(e) => updateCell(rowIndex, colIndex, e.target.value)}
                />
              ))}
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}

export default App;
